void abort(void);
void exit(int);

long a = 1;

int foo(void) {
  switch (a % 2 % 2 % 2 % 2 % 2 % 2 % 2 % 2) {
  case 0:
    return 0;
  case 1:
    return 1;
  default:
    return -1;
  }
}

int main(void) {
  if (foo() != 1)
    abort();
  exit(0);
}


